const templates: Record<string, string> = {
  "change_log": "{% for (var i=0, l=change_log.length; i < l; i++) {\r\n    var app_info = change_log[i]; %}\r\n\t{% if (i > 0) { %} <hr> {% } %}\r\n\t<div class=\"text-left app-change-log\">\r\n\t\t<h2 style=\"margin-top: 10px;\">\r\n            {{ app_info.title }}\r\n\t\t\t<small>{{ __(\"updated to {0}\", [app_info.version]) }}</small>\r\n\t\t</h2>\r\n\t\t<div class=\"app-change-log-body\">\r\n\t\t{% for (var x=0, y=app_info.change_log.length; x < y; x++) {\r\n            var version_info = app_info.change_log[x];\r\n            if(version_info) { %}\r\n    \t\t\t<p>{{ frappe.markdown(version_info[1]) }}</p>\r\n\t\t    {% }\r\n        } %}\r\n    \t</div>\r\n\t</div>\r\n{% } %}\r\n",
  "address_list": "{% if (addr_list.length) { %}\r\n\t<div class=\"card-list-actions\">\r\n\t\t{%= frappe.ui.button.html({ label: __(\"Address\"), icon: \"plus\", size: \"sm\", css_class: \"btn-address\" }) %}\r\n\t</div>\r\n{% } %}\r\n\r\n<div class=\"clearfix\"></div>\r\n{% for (const addr of addr_list) { %}\r\n\t<div class=\"address-box\" data-name=\"{%= frappe.utils.escape_html(addr.name) %}\">\r\n\t\t{%= frappe.ui.button.html({ icon: \"ellipsis\", variant: \"ghost\", size: \"sm\", title: __(\"Options\"), css_class: \"card-menu-btn\" }) %}\r\n\t\t<div class=\"box-header flex items-center flex-wrap gap-2\">\r\n\t\t\t<span class=\"text-base-semibold text-ink-gray-8\">{%= frappe.utils.escape_html(addr.address_title) %}</span>\r\n\t\t\t{% if (addr.name === primary_name) { %}\r\n\t\t\t\t{%= frappe.ui.badge.html({ label: __(\"Primary\"), size: \"sm\" }) %}\r\n\t\t\t{% } %}\r\n\t\t</div>\r\n\t\t{% const tags = [addr.address_type !== \"Other\" ? frappe.utils.escape_html(__(addr.address_type)) : null, addr.is_shipping_address ? __(\"Shipping\") : null, addr.disabled ? __(\"Disabled\") : null].filter(Boolean).join(\" · \"); %}\r\n\t\t{% if (tags) { %}\r\n\t\t\t<div class=\"box-subtitle text-sm text-ink-gray-5\">{%= tags %}</div>\r\n\t\t{% } %}\r\n\t\t<div class=\"address-display text-ink-gray-7\">{%= addr.display %}</div>\r\n\t</div>\r\n{% } %}\r\n\r\n{% if (!addr_list.length) { %}\r\n\t{%= frappe.ui.empty_state.html({\r\n\t\ticon: \"map-pin\",\r\n\t\ttitle: __(\"No addresses added yet\"),\r\n\t\tactions: [{ label: __(\"New Address\"), icon: \"plus\", css_class: \"btn-address\" }],\r\n\t}) %}\r\n{% } %}\r\n",
  "contact_list": "{% if (contact_list.length) { %}\r\n\t<div class=\"card-list-actions\">\r\n\t\t{%= frappe.ui.button.html({ label: __(\"Contact\"), icon: \"plus\", size: \"sm\", css_class: \"btn-contact\" }) %}\r\n\t</div>\r\n{% } %}\r\n\r\n<div class=\"clearfix\"></div>\r\n{% for (const contact of contact_list) { %}\r\n\t<div class=\"contact-box\" data-name=\"{%= frappe.utils.escape_html(contact.name) %}\">\r\n\t\t{%= frappe.ui.button.html({ icon: \"ellipsis\", variant: \"ghost\", size: \"sm\", title: __(\"Options\"), css_class: \"card-menu-btn\" }) %}\r\n\t\t<div class=\"box-header flex items-center flex-wrap gap-2\">\r\n\t\t\t<span class=\"text-base-semibold text-ink-gray-8\">{%= frappe.utils.escape_html(contact.first_name) %} {%= frappe.utils.escape_html(contact.last_name) %}</span>\r\n\t\t\t{% if (contact.name === primary_name) { %}\r\n\t\t\t\t{%= frappe.ui.badge.html({ label: __(\"Primary\"), size: \"sm\" }) %}\r\n\t\t\t{% } %}\r\n\t\t</div>\r\n\t\t{% if (contact.is_billing_contact) { %}\r\n\t\t\t<div class=\"box-subtitle text-sm text-ink-gray-5\">{%= __(\"Billing\") %}</div>\r\n\t\t{% } %}\r\n\t\t{% let mobile_no = contact.mobile_no !== contact.phone ? contact.mobile_no : \"\"; %}\r\n\t\t{% if (contact.designation) { %}\r\n\t\t\t<div class=\"contact-line flex items-center gap-2 text-ink-gray-7\" title=\"{%= __(\"Designation\") %}\">\r\n\t\t\t\t{%= frappe.utils.icon(\"briefcase\", \"sm\", \"\", \"\", \"text-ink-gray-5\", true) %}\r\n\t\t\t\t<span>{%= frappe.utils.escape_html(contact.designation) %}</span>\r\n\t\t\t</div>\r\n\t\t{% } %}\r\n\t\t{% if (contact.phone) { %}\r\n\t\t\t<div class=\"contact-line flex items-center gap-2 text-ink-gray-7\">\r\n\t\t\t\t{%= frappe.utils.icon(\"phone\", \"sm\", \"\", \"\", \"text-ink-gray-5\", true) %}\r\n\t\t\t\t<a href=\"tel:{%= frappe.utils.escape_html(contact.phone) %}\" title=\"{%= __(\"Primary Phone\") %}\">{%= frappe.utils.escape_html(contact.phone) %}</a>\r\n\t\t\t</div>\r\n\t\t{% } %}\r\n\t\t{% if (mobile_no) { %}\r\n\t\t\t<div class=\"contact-line flex items-center gap-2 text-ink-gray-7\">\r\n\t\t\t\t{%= frappe.utils.icon(\"smartphone\", \"sm\", \"\", \"\", \"text-ink-gray-5\", true) %}\r\n\t\t\t\t<a href=\"tel:{%= frappe.utils.escape_html(mobile_no) %}\" title=\"{%= __(\"Primary Mobile\") %}\">{%= frappe.utils.escape_html(mobile_no) %}</a>\r\n\t\t\t</div>\r\n\t\t{% } %}\r\n\t\t{% if (contact.email_id) { %}\r\n\t\t\t<div class=\"contact-line flex items-center gap-2 text-ink-gray-7\">\r\n\t\t\t\t{%= frappe.utils.icon(\"mail\", \"sm\", \"\", \"\", \"text-ink-gray-5\", true) %}\r\n\t\t\t\t<a href=\"mailto:{%= frappe.utils.escape_html(contact.email_id) %}\" title=\"{%= __(\"Primary Email\") %}\">{%= frappe.utils.escape_html(contact.email_id) %}</a>\r\n\t\t\t</div>\r\n\t\t{% } %}\r\n\t\t{% if (!contact.designation && !contact.phone && !mobile_no && !contact.email_id) { %}\r\n\t\t\t<div class=\"contact-line text-sm text-ink-gray-4\">{%= __(\"No contact details\") %}</div>\r\n\t\t{% } %}\r\n\t</div>\r\n{% } %}\r\n\r\n{% if (!contact_list.length) { %}\r\n\t{%= frappe.ui.empty_state.html({\r\n\t\ticon: \"user\",\r\n\t\ttitle: __(\"No contacts added yet\"),\r\n\t\tactions: [{ label: __(\"New Contact\"), icon: \"plus\", css_class: \"btn-contact\" }],\r\n\t}) %}\r\n{% } %}\r\n",
  "form_dashboard": "<div class=\"form-dashboard-wrapper\">\r\n\t<div class=\"progress-area hidden form-dashboard-section\">\r\n\t</div>\r\n\t<div class=\"form-heatmap hidden form-dashboard-section\">\r\n\t\t<div class=\"section-head\">{{ __(\"Overview\") }}</div>\r\n\t\t<div id=\"heatmap-{{ frappe.model.scrub(frm.doctype) }}\" class=\"heatmap\"></div>\r\n\t\t<div class=\"text-muted small heatmap-message hidden\"></div>\r\n\t</div>\r\n\t<div class=\"form-graph form-dashboard-section hidden\">\r\n\t\t<div class=\"section-head\">{{ __(\"Graph\") }}</div>\r\n\t</div>\r\n\t<div class=\"form-stats form-dashboard-section hidden\">\r\n\t\t<div class=\"section-head\">{{ __(\"Stats\") }}</div>\r\n\t\t<div class=\"row\"></div>\r\n\t</div>\r\n\t<div class=\"form-links form-dashboard-section hidden\">\r\n\t\t<div class=\"section-head\">{{ __(\"Documents\") }}</div>\r\n\t\t<div class=\"transactions\"></div>\r\n\t</div>\r\n</div>",
  "form_footer": "<div class=\"form-footer\">\r\n\t<div class=\"after-save\">\r\n\t\t<div class=\"comment-box\"></div>\r\n\t\t<div class=\"timeline\"></div>\r\n\t</div>\r\n\t<button class=\"scroll-to-top btn btn-default icon-btn\" onclick=\"frappe.utils.scroll_page_to_top()\">\r\n\t\t<svg class=\"icon icon-xs\"><use href=\"#icon-chevron-up\"></use></svg>\r\n\t</button>\r\n</div>\r\n",
  "form_links": "<div class=\"form-documents\">\r\n\t{% for (let i=0; i < transactions.length; i++) { %}\r\n\t\t{% if (i % 3 === 0) { %}\r\n\t\t<div class=\"row\">\r\n\t\t{% } %}\r\n\t\t\t<div class=\"col-md-4\">\r\n\t\t\t\t<div class=\"form-link-title\">\r\n\t\t\t\t\t<span>{{ __(transactions[i].label) }}</span>\r\n\t\t\t\t</div>\r\n\t\t\t\t{% for (let j=0; j < transactions[i].items.length; j++) { %}\r\n\t\t\t\t\t{% let doctype = transactions[i].items[j]; %}\r\n\t\t\t\t\t{% let fieldname = (transactions[i].fieldnames && transactions[i].fieldnames[doctype]) || transactions[i].fieldname; %}\r\n\t\t\t\t\t<div class=\"document-link\" data-doctype=\"{{ doctype }}\">\r\n\t\t\t\t\t\t<div class=\"document-link-badge\" data-doctype=\"{{ doctype }}\" data-fieldname=\"{{ fieldname }}\">\r\n\t\t\t\t\t\t\t<a class=\"badge-link\">{{ __(doctype) }}</a>\r\n\t\t\t\t\t\t\t<span class=\"count hidden\"></span>\r\n\t\t\t\t\t\t</div>\r\n\t\t\t\t\t\t<span class=\"open-notification hidden\"\r\n\t\t\t\t\t\t\ttitle=\"{{ __(\"Open {0}\", [__(doctype)])}}\">\r\n\t\t\t\t\t\t</span>\r\n\t\t\t\t\t\t{% if !internal_links[doctype] %}\r\n\t\t\t\t\t\t\t<button class=\"btn btn-new btn-secondary btn-xs icon-btn hidden\"\r\n\t\t\t\t\t\t\t\tdata-doctype=\"{{ doctype }}\"\r\n\t\t\t\t\t\t\t\tdata-fieldname=\"{{ fieldname }}\">\r\n\t\t\t\t\t\t\t\t<svg class=\"icon icon-sm\"><use href=\"#icon-plus\"></use></svg>\r\n\t\t\t\t\t\t\t</button>\r\n\t\t\t\t\t\t{% endif %}\r\n\t\t\t\t\t</div>\r\n\t\t\t\t{% } %}\r\n\t\t\t</div>\r\n\t\t{% if (i % 3 === 2 || i === (transactions.length - 1)) { %}\r\n\t\t</div>\r\n\t\t{% } %}\r\n\t{% } %}\r\n</div>\r\n",
  "form_sidebar": "<div class=\"flex justify-between sidebar-image-section sidebar-section hide\">\r\n\t<div class=\"sidebar-image-wrapper\">\r\n\t\t<img class=\"sidebar-image\">\r\n\t\t<div class=\"sidebar-standard-image\">\r\n\t\t\t<div class=\"standard-image\"></div>\r\n\t\t</div>\r\n\t\t{% if can_write %}\r\n\t\t<div class=\"sidebar-image-actions\">\r\n\t\t\t<div class=\"sidebar-image-upload-hint\">\r\n\t\t\t\t<svg class=\"icon icon-sm\"><use href=\"#icon-camera\"></use></svg>\r\n\t\t\t</div>\r\n\t\t\t<a class=\"sidebar-image-remove\">\r\n\t\t\t\t<svg class=\"icon icon-sm\"><use href=\"#icon-x\"></use></svg>\r\n\t\t\t</a>\r\n\t\t</div>\r\n\t\t{% endif %}\r\n\t</div>\r\n\t{% if image_field %}\r\n\t<div class=\"align-items-baseline flex form-stats-likes\">\r\n\t\t<div class=\"form-title-edit\"></div>\r\n\t\t<div class=\"form-print\"></div>\r\n\t\t<span class=\"liked-by like-action d-flex align-items-center\">\r\n\t\t\t<svg class=\"icon icon-sm like-icon pointer\">\r\n\t\t\t\t<use href=\"#icon-heart\"></use>\r\n\t\t\t</svg>\r\n\t\t</span>\r\n\t</div>\r\n\t{% endif %}\r\n</div>\r\n<div class=\"sidebar-section sidebar-meta-details border-bottom\">\r\n\t<div class=\"flex justify-between overflow-hidden\">\r\n\t\t<div class=\"ellipsis\">\r\n\t\t\t{% let title = frm.get_title(); %}\r\n\t\t\t<div class=\"form-details flex justify-between form-title-text\"  data-copy=\"{%= frappe.utils.escape_html(frappe.utils.html2text(title)) %}\">\r\n\t\t\t\t<span class=\"bold ellipsis mr-3 text-medium\">{%= frappe.utils.escape_html(frappe.utils.html2text(title)) %}</span>\r\n\t\t\t</div>\r\n\t\t\t{% if frm.meta.beta %}\r\n\t\t\t<div class=\"pt-1\">\r\n\t\t\t\t{%= frappe.ui.badge.html({\r\n\t\t\t\t\tlabel: __(\"Experimental\"),\r\n\t\t\t\t\ttheme: \"amber\",\r\n\t\t\t\t\ticon: \"flask-conical\",\r\n\t\t\t\t\ttitle: __(\"This feature is brand new and still experimental\"),\r\n\t\t\t\t}) %}\r\n\t\t\t</div>\r\n\t\t\t{% endif %}\r\n\t\t\t{% if frm.meta.deprecated %}\r\n\t\t\t<div class=\"pt-1\">\r\n\t\t\t\t{%= frappe.ui.badge.html({\r\n\t\t\t\t\tlabel: __(\"Deprecated\"),\r\n\t\t\t\t\ttheme: \"red\",\r\n\t\t\t\t\ttitle: __(\"This feature is deprecated and may be removed in a future release\"),\r\n\t\t\t\t}) %}\r\n\t\t\t</div>\r\n\t\t\t{% endif %}\r\n\t\t\t{% if (title && title !== frm.doc.name) { %}\r\n\t\t\t<div class=\"form-name-container mt-1 flex justify-between form-name-copy\" data-copy=\"{%= frappe.utils.escape_html(frappe.utils.html2text(frm.doc.name)) %}\" title=\"{%= frappe.utils.escape_html(frappe.utils.html2text(frm.doc.name)) %}\" >\r\n\t\t\t\t<span class=\"ellipsis mr-3\">{%= frappe.utils.escape_html(frappe.utils.html2text(frm.doc.name)) %}</span>\r\n\t\t\t</div>\r\n\t\t\t{% } %}\r\n\t\t</div>\r\n\t\t{% if not image_field %}\r\n\t\t<div class=\"align-items-baseline flex form-stats-likes\">\r\n\t\t\t<div class=\"form-title-edit\"></div>\r\n\t\t\t<div class=\"form-print\"></div>\r\n\t\t\t<span class=\"liked-by like-action d-flex align-items-center\">\r\n\t\t\t\t<svg class=\"icon icon-sm like-icon pointer\">\r\n\t\t\t\t\t<use href=\"#icon-heart\"></use>\r\n\t\t\t\t</svg>\r\n\t\t\t</span>\r\n\t\t</div>\r\n\t\t{% endif %}\r\n\t</div>\r\n</div>\r\n<div class=\"sidebar-section sidebar-rating hide border-bottom\">\r\n\t<div style=\"position: relative;\">\r\n\t\t<a class=\"strong badge-hover\">\r\n\t\t\t<span>{%= __(\"Feedback\") %}</span>\r\n\t\t</a>\r\n\t</div>\r\n\t<div class=\"rating-icons\"></div>\r\n</div>\r\n<div class=\"sidebar-section hidden border-bottom\">\r\n\t{% if (frappe.help.has_help(doctype)) { %}\r\n\t<div>\r\n\t\t<a class=\"help-link list-link\" data-doctype=\"{{ doctype }}\">{{ __(\"Help\") }}</a>\r\n\t</div>\r\n\t{% } %}\r\n</div>\r\n<div class=\"sidebar-section user-actions hidden border-bottom\">\r\n\t<div class=\"form-sidebar-items user-actions-header\">\r\n\t\t<div class=\"form-sidebar-label\">\r\n\t\t\t{%= frappe.utils.icon(\"link-2\") %}\r\n\t\t\t<span class=\"ellipsis\">{%= __(\"Links\") %}</span>\r\n\t\t</div>\r\n\t</div>\r\n\t<div class=\"user-actions-list\"></div>\r\n</div>\r\n<div class=\"sidebar-section form-assignments\">\r\n\t<div>\r\n\t\t<span class=\"form-sidebar-items\">\r\n\t\t\t<span class=\"add-assignment-label form-sidebar-label\">\r\n\t\t\t\t{%= frappe.utils.icon(\"users\") %}\r\n\t\t\t\t<span class=\"ellipsis\">{%= __(\"Assign\") %}</span>\r\n\t\t\t</span>\r\n\t\t\t{%= frappe.ui.button.html({\r\n\t\t\t\ticon: \"plus\",\r\n\t\t\t\tvariant: \"ghost\",\r\n\t\t\t\ttitle: __(\"Assign\"),\r\n\t\t\t\tcss_class: \"add-assignment-btn\",\r\n\t\t\t}) %}\r\n\t\t</span>\r\n\t\t<div class=\"assignments\"></div>\r\n\t</div>\r\n</div>\r\n<div class=\"sidebar-section form-attachments\">\r\n\t<div class=\"attachments-actions\">\r\n\t\t<span class=\"form-sidebar-items\">\r\n\t\t\t<span>\r\n\t\t\t\t<a class=\"pill-label ellipsis form-sidebar-label explore-link\">\r\n\t\t\t\t\t{%= frappe.utils.icon(\"paperclip\") %}\r\n\t\t\t\t\t{%= __(\"Attachments\") %}\r\n\t\t\t\t</a>\r\n\t\t\t</span>\r\n\t\t\t{%= frappe.ui.button.html({\r\n\t\t\t\ticon: \"plus\",\r\n\t\t\t\tvariant: \"ghost\",\r\n\t\t\t\ttitle: __(\"Add attachment\"),\r\n\t\t\t\tcss_class: \"add-attachment-btn\",\r\n\t\t\t}) %}\r\n\t\t</span>\r\n\t</div>\r\n\t<a class=\"show-all-btn hidden\" href=\"\">\r\n\t\t<span class=\"pill-label ellipsis\">\r\n\t\t\t{%= __(\"Show All\") %}\r\n\t\t</span>\r\n\t</a>\r\n</div>\r\n<div class=\"sidebar-section form-tags\">\r\n\t<div>\r\n\t\t<span class=\"form-sidebar-items\">\r\n\t\t\t<div class=\"form-sidebar-label\">\r\n\t\t\t\t{%= frappe.utils.icon(\"tag\") %}\r\n\t\t\t\t<span class=\"tags-label ellipsis\">{%= __(\"Tags\") %}</span>\r\n\t\t\t</div>\r\n\t\t</span>\r\n\t</div>\r\n</div>\r\n<div class=\"sidebar-section form-shared border-bottom\">\r\n\t<div>\r\n\t\t<span class=\"form-sidebar-items\">\r\n\t\t\t<span class=\"share-label form-sidebar-label\">\r\n\t\t\t\t{%= frappe.utils.icon(\"share-2\") %}\r\n\t\t\t\t<span class=\"ellipsis\">{%= __(\"Share\") %}</span>\r\n\t\t\t</span>\r\n\t\t\t{%= frappe.ui.button.html({\r\n\t\t\t\ticon: \"plus\",\r\n\t\t\t\tvariant: \"ghost\",\r\n\t\t\t\ttitle: __(\"Share\"),\r\n\t\t\t\tcss_class: \"share-doc-btn\",\r\n\t\t\t}) %}\r\n\t\t</span>\r\n\t\t<div class=\"shares\"></div>\r\n\t</div>\r\n</div>\r\n<div class=\"sidebar-section hidden\">\r\n\t<a><li class=\"indicator blue auto-repeat-status\" style=\"display: none;\"></li></a>\r\n</div>\r\n<div class=\"sidebar-section text-muted pt-3\">\r\n\t<ul class=\"list-unstyled sidebar-menu text-muted\">\r\n\t\t<li class=\"modified-by\"></li>\r\n\t\t<li class=\"created-by\"></li>\r\n\t\t<li class=\"pageview-count\"></li>\r\n\t</ul>\r\n</div>\r\n\r\n{% if(frappe.get_form_sidebar_extension) { %}\r\n\t{{ frappe.get_form_sidebar_extension() }}\r\n{% } %}\r\n",
  "print_layout": "<!-- <div class=\"form-print-wrapper frappe-card\">\r\n\t<div class=\"print-toolbar row\">\r\n\t\t<div class=\"col-xs-3\">\r\n\t\t\t<div class=\"flex\">\r\n\t\t\t\t<select class=\"print-preview-select input-sm form-control\"></select>\r\n\t\t\t\t<button class=\"btn btn-default btn-sm border print-preview-refresh\" type=\"button\">{%= __(\"Refresh\") %}</button>\r\n\t\t\t</div>\r\n\t\t</div>\r\n\t\t<div class=\"col-xs-2\">\r\n\t\t\t<select class=\"languages input-sm form-control\"\r\n\t\t\t\tplaceholder=\"{{ __(\"Language\") }}\"></select></div>\r\n\t\t<div class=\"col-xs-2\">\r\n\t\t\t<div class=\"checkbox small\" style=\"margin-top: 7px; margin-bottom: 0px;\">\r\n\t\t\t\t<label>\r\n\t\t\t\t\t<input type=\"checkbox\" class=\"print-letterhead text-muted\"/>\r\n\t\t\t\t\t{%= __(\"Letter Head\") %}</label>\r\n\t\t\t</div>\r\n\t\t</div>\r\n\t\t<div class=\"col-xs-5 text-right\">\r\n\t\t\t<a class=\"close btn-print-close\" style=\"margin-top: 2px; margin-left: 10px;\">&times;</a>\r\n\t\t\t<div class=\"btn-group\">\r\n\t\t\t\t<a class=\"btn btn-default btn-sm\"\r\n\t\t\t\t\tstyle=\"border-top-right-radius:0px; border-bottom-right-radius: 0px;\"\r\n\t\t\t\t\tdata-toggle=\"dropdown\" aria-haspopup=\"true\" aria-expanded=\"false\">\r\n\t\t\t\t\t<span>{%= __(\"Settings\") %}</span>\r\n\t\t\t\t\t<span>\r\n\t\t\t\t\t\t<svg class=\"icon icon-xs\">\r\n\t\t\t\t\t\t\t<use href=\"#icon-chevrons-up-down\"></use>\r\n\t\t\t\t\t\t</svg>\r\n\t\t\t\t\t</span>\r\n\t\t\t\t</a>\r\n\t\t\t\t<ul class=\"dropdown-menu print-format-dropdown\" style=\"max-height: 300px;\r\n\t\t\t\t\toverflow-y: auto; left: auto;\">\r\n\t\t\t\t\t<li><a class=\"dropdown-item\" href=\"/desk/Form/Print Settings\">\r\n\t\t\t\t\t\t{%= __(\"Print Settings\") %}</a></li>\r\n\t\t\t\t\t<li><a class=\"btn-printer-setting dropdown-item\" style=\"display: none;\">\r\n\t\t\t\t\t\t{%= __(\"Raw Printing Settings\") %}</a></li>\r\n\t\t\t\t\t<li><a class=\"btn-print-edit dropdown-item\">\r\n\t\t\t\t\t\t{%= __(\"Customize\") %}</a></li>\r\n\t\t\t\t</ul>\r\n\t\t\t\t<a class=\"btn-print-preview btn-sm btn btn-default\">\r\n\t\t\t\t\t{%= __(\"Full Page\") %}</a>\r\n\t\t\t\t<a class=\"btn-download-pdf btn-sm btn btn-default\">\r\n\t\t\t\t\t{%= __(\"PDF\") %}</a>\r\n\t\t\t\t<a class=\"btn-print-print btn-sm btn btn-default\">\r\n\t\t\t\t\t<strong>{%= __(\"Print\") %}</strong></a>\r\n\t\t\t</div>\r\n\t\t</div>\r\n\t</div>\r\n\t<div class=\"print-preview-wrapper\">\r\n\t\t<div class=\"print-preview\">\r\n\t\t\t<div class=\"print-format\"></div>\r\n\t\t</div>\r\n\t\t<div class=\"page-break-message text-muted text-center text-medium margin-top\"></div>\r\n\t</div>\r\n</div> -->\r\n",
  "report_links": "<div class=\"form-documents\">\r\n\t{% for (var i=0; i < reports.length; i++) { %}\r\n\t\t{% if (i % 3 === 0) { %}\r\n\t\t<div class=\"row\">\r\n\t\t{% } %}\r\n\t\t\t<div class=\"col-md-4\">\r\n\t\t\t\t<div class=\"form-link-title\">\r\n\t\t\t\t\t<span>{{ __(reports[i].label) }}</span>\r\n\t\t\t\t</div>\r\n\t\t\t\t{% for (let j=0; j < reports[i].items.length; j++) { %}\r\n\t\t\t\t\t{% let report = reports[i].items[j]; %}\r\n\t\t\t\t\t<div class=\"document-link\" data-report=\"{{ report }}\">\r\n\t\t\t\t\t\t<div class=\"report-link-badge\" data-report=\"{{ report }}\">\r\n\t\t\t\t\t\t\t<a class=\"report-link\">{{ __(report) }}</a>\r\n\t\t\t\t\t\t</div>\r\n\t\t\t\t\t</div>\r\n\t\t\t\t{% } %}\r\n\t\t\t</div>\r\n\t\t{% if (i % 3 === 2 || i === (reports.length - 1)) { %}\r\n\t\t</div>\r\n\t\t{% } %}\r\n\t{% } %}\r\n</div>\r\n",
  "set_sharing": "{% var standard_perms = [\r\n\t{name: \"read\", label: __(\"Read\"), disable_check: false},\r\n\t{name: \"write\", label: __(\"Write\"), disable_check: true},\r\n\t{name: \"submit\", label: __(\"Submit\"), disable_check: true},\r\n\t{name: \"share\", label: __(\"Share\"), disable_check: false}\r\n];\r\n\r\nvar custom_perms = (custom_perm_types || []).map(function(perm) {\r\n\treturn {\r\n\t\tname: perm,\r\n\t\tlabel: __(frappe.model.unscrub(perm)),\r\n\t\tdisable_check: true\r\n\t};\r\n});\r\n\r\nvar all_perms = standard_perms.concat(custom_perms);\r\n%}\r\n<div>\r\n\t<div style=\"display: grid; grid-template-columns: 2fr repeat({%= all_perms.length %}, 1fr); gap: 8px; align-items: center;\">\r\n\t\t<div><h6>{%= __(\"User\") %}</h6></div>\r\n\t\t{% for (var i=0; i < all_perms.length; i++) { var perm = all_perms[i]; %}\r\n\t\t\t<div style=\"display: flex; justify-content: center; align-items: center;\"><h6>{%= perm.label %}</h6></div>\r\n\t\t{% } %}\r\n\t</div>\r\n\r\n\t<div class=\"shared-user\" data-everyone=1 style=\"display: grid; grid-template-columns: 2fr repeat({%= all_perms.length %}, 1fr); gap: 8px; align-items: center;\">\r\n\t\t<div class=\"share-all\"><b>{{ __(\"Everyone\") }}</b></div>\r\n\t\t{% for (var i=0; i < all_perms.length; i++) {\r\n\t\t\tvar perm = all_perms[i];\r\n\t\t\tvar is_disabled = perm.disable_check && !frm.perm[0][perm.name]; %}\r\n\t\t<div style=\"display: flex; justify-content: center; align-items: center;\">\r\n\t\t\t<input type=\"checkbox\" name=\"{%= perm.name %}\"\r\n\t\t\t\t{% if(cint(everyone[perm.name])) { %}checked{% } %}\r\n\t\t\t\t{% if (is_disabled) { %}disabled=\"disabled\"{% } %}\r\n\t\t\t\tclass=\"edit-share\">\r\n\t\t</div>\r\n\t\t{% } %}\r\n\t</div>\r\n\r\n\t{% for (var i=0, l=shared.length; i < l; i++) {\r\n\t\tvar s = shared[i]; %}\r\n\t\t{% if(s && !s.everyone) { %}\r\n\t\t<div class=\"shared-user\" data-user=\"{%= s.user %}\" data-name=\"{%= s.name %}\" style=\"display: grid; grid-template-columns: 2fr repeat({%= all_perms.length %}, 1fr); gap: 8px; align-items: center;\">\r\n\t\t\t<div>{%= s.user %}</div>\r\n\t\t\t{% for (var j=0; j < all_perms.length; j++) {\r\n\t\t\t\tvar perm = all_perms[j];\r\n\t\t\t\tvar is_disabled = perm.disable_check && !frm.perm[0][perm.name]; %}\r\n\t\t\t<div style=\"display: flex; justify-content: center; align-items: center;\">\r\n\t\t\t\t<input type=\"checkbox\" name=\"{%= perm.name %}\"\r\n\t\t\t\t\t{% if(cint(s[perm.name])) { %}checked{% } %}\r\n\t\t\t\t\t{% if (is_disabled) { %}disabled=\"disabled\"{% } %}\r\n\t\t\t\t\tclass=\"edit-share\">\r\n\t\t\t</div>\r\n\t\t\t{% } %}\r\n\t\t</div>\r\n\t\t{% } %}\r\n\t{% } %}\r\n\r\n\t{% if(frappe.model.can_share(null, frm)) { %}\r\n\t<hr>\r\n\r\n\t<div style=\"display: grid; grid-template-columns: 2fr repeat({%= all_perms.length %}, 1fr); gap: 8px; align-items: center;\">\r\n\t\t<div><h6>{%= __(\"Share this document with\") %}</h6></div>\r\n\t\t{% for (var i=0; i < all_perms.length; i++) {\r\n\t\t\tvar perm = all_perms[i]; %}\r\n\t\t<div style=\"display: flex; justify-content: center; align-items: center;\"><h6>{%= perm.label %}</h6></div>\r\n\t\t{% } %}\r\n\t</div>\r\n\r\n\t<div style=\"display: grid; grid-template-columns: 2fr repeat({%= all_perms.length %}, 1fr); gap: 8px; align-items: center;\">\r\n\t\t<div class=\"input-wrapper-add-share\"></div>\r\n\t\t{% for (var i=0; i < all_perms.length; i++) {\r\n\t\t\tvar perm = all_perms[i];\r\n\t\t\tvar is_disabled = perm.disable_check && !frm.perm[0][perm.name]; %}\r\n\t\t<div style=\"display: flex; justify-content: center; align-items: flex-start; margin-top: 8px;\">\r\n\t\t\t<input type=\"checkbox\" class=\"add-share-{%= perm.name %}\" name=\"{%= perm.name %}\"\r\n\t\t\t\t{% if (is_disabled) { %}disabled=\"disabled\"{% } %}>\r\n\t\t</div>\r\n\t\t{% } %}\r\n\t</div>\r\n\t<div>\r\n\t\t{%= frappe.ui.button.html({\r\n\t\tlabel: __(\"Add\"),\r\n\t\tvariant: \"solid\",\r\n\t\tcss_class: \"btn-add-share\",\r\n\t\tattrs: { style: \"margin-top: 12px;\" },\r\n\t}) %}\r\n\t</div>\r\n\t{% endif %}\r\n</div>\r\n",
  "timeline_message_box": "<div class=\"timeline-message-box\" data-communication-type=\"{{ doc.communication_type }}\">\r\n\t{% is_mini = frappe.is_mobile() ? true : false %}\r\n\t{% var show_absolute_datetime = cint(frappe.boot.user.show_absolute_datetime_in_timeline) || cint(frappe.boot.sysdefaults.show_absolute_datetime_in_timeline) %}\r\n\t<span class=\"flex justify-between m-1 mb-3\">\r\n\t\t<span class=\"text-color flex\">\r\n\t\t\t{% if (doc.communication_type && doc.communication_type == \"Automated Message\") { %}\r\n\t\t\t\t<span>\r\n\t\t\t\t\t<!-- Display maximum of 3 users-->\r\n\t\t\t\t\t{{ __(\"Notification sent to\") }}\r\n\t\t\t\t\t{% var recipients = (doc.recipients && doc.recipients.split(\",\")) || [] %}\r\n\t\t\t\t\t{% var cc = (doc.cc && doc.cc.split(\",\")) || [] %}\r\n\t\t\t\t\t{% var bcc = (doc.bcc && doc.bcc.split(\",\")) || [] %}\r\n\t\t\t\t\t{% var emails = recipients.concat(cc, bcc) %}\r\n\t\t\t\t\t{% var display_emails_len = Math.min(emails.length, 3) %}\r\n\r\n\t\t\t\t\t{% for (var i=0, len=display_emails_len; i<len; i++) { var email = emails[i]; %}\r\n\t\t\t\t\t\t{{ frappe.user_info(email).fullname || email }}\r\n\t\t\t\t\t\t{% if (len > i+1) { %}\r\n\t\t\t\t\t\t\t{{ \",\" }}\r\n\t\t\t\t\t\t{% } %}\r\n\t\t\t\t\t{% } %}\r\n\r\n\t\t\t\t\t{% if (emails.length > display_emails_len) { %}\r\n\t\t\t\t\t\t{{ \"...\" }}\r\n\t\t\t\t\t{% } %}\r\n\r\n\t\t\t\t\t<div class=\"text-extra-muted\">\r\n\t\t\t\t\t\t{{ show_absolute_datetime ? frappe.datetime.str_to_user(doc.communication_date || doc.creation) : comment_when(doc.communication_date || doc.creation) }}\r\n\t\t\t\t\t</div>\r\n\t\t\t\t</span>\r\n\t\t\t{% } else if (doc.comment_type && doc.comment_type == \"Comment\") { %}\r\n\t\t\t\t<span>\r\n\t\t\t\t\t\t{{ frappe.avatar(doc.owner, \"avatar-medium\") }}\r\n\t\t\t\t\t\t<span class=\"ml-2\" style=\"font-size: var(--text-base);\">{{ doc.user_full_name || frappe.user.full_name(doc.owner) }}</span>\r\n\t\t\t\t\t\t<span class=\"text-extra-muted\">{{ __(\"commented\") }}</span>\r\n\t\t\t\t\t\t<span> · </span>\r\n\t\t\t\t\t\t<span class=\"text-extra-muted\">\r\n\t\t\t\t\t\t\t{{ show_absolute_datetime ? frappe.datetime.str_to_user(doc.communication_date || doc.creation) : comment_when(doc.communication_date || doc.creation, is_mini) }}\r\n\t\t\t\t\t\t</span>\r\n\t\t\t\t\t{% if (doc.published) { %}\r\n\t\t\t\t\t\t<span> · </span>\r\n\t\t\t\t\t\t<span class=\"text-extra-muted\" title=\"{{ __('Visible to website/portal users.') }}\">\r\n\t\t\t\t\t\t\t{{ __(\"Published\") }}\r\n\t\t\t\t\t\t</span>\r\n\t\t\t\t\t{% } %}\r\n\t\t\t\t</span>\r\n\t\t\t{% } else { %}\r\n\t\t\t\t<span class=\"margin-right\">\r\n\t\t\t\t\t{{ frappe.avatar(doc.owner, \"avatar-medium\") }}\r\n\t\t\t\t</span>\r\n\t\t\t\t\t<div>\r\n\t\t\t\t\t\t{{ doc.user_full_name || frappe.user.full_name(doc.owner) }}\r\n\t\t\t\t\t\t<span> . </span>\r\n\r\n\t\t\t\t\t\t<span class=\"text-muted\">\r\n\t\t\t\t\t\t\t{{ show_absolute_datetime ? frappe.datetime.str_to_user(doc.communication_date || doc.creation) : comment_when(doc.communication_date || doc.creation, is_mini) }}\r\n\t\t\t\t\t\t</span>\r\n\t\t\t\t\t\t{% if (doc.subject) { %}\r\n\t\t\t\t\t\t\t<div class=\"text-muted my-1\">{{doc.subject}}</div>\r\n\t\t\t\t\t\t{% } %}\r\n\t\t\t\t\t</div>\r\n\t\t\t{% } %}\r\n\t\t</span>\r\n\t\t<span class=\"actions\" style=\"flex-shrink: 0\">\r\n\t\t\t{% if (doc._doc_status && doc._doc_status_indicator) { %}\r\n\t\t\t{%= frappe.ui.badge.html({\r\n\t\t\t\tlabel: __(doc._doc_status),\r\n\t\t\t\ttheme: doc._doc_status_indicator,\r\n\t\t\t\ttitle: __(doc._doc_status),\r\n\t\t\t\tattrs: { style: \"order: -1\" },\r\n\t\t\t}) %}\r\n\t\t\t{% } %}\r\n\r\n\t\t\t{% if (doc._url && !frappe.is_mobile()) { %}\r\n\t\t\t<a class=\"action-btn\" href=\"{{ doc._url }}\" title=\"{{ __(\"Open Communication\") }}\">\r\n\t\t\t\t<svg class=\"icon\">\r\n\t\t\t\t\t<use href=\"#icon-link\"></use>\r\n\t\t\t\t</svg>\r\n\t\t\t</a>\r\n\t\t\t{% } %}\r\n\t\t\t<div class=\"custom-actions\"></div>\r\n\t\t\t<div class=\"more-actions\">\r\n\t\t\t\t<a type=\"button\" class=\"action-btn\"\r\n\t\t\t\t\tdata-toggle=\"dropdown\" aria-haspopup=\"true\" aria-expanded=\"false\">\r\n\t\t\t\t\t<svg class=\"icon icon-sm\">\r\n\t\t\t\t\t\t<use href=\"#icon-ellipsis\"></use>\r\n\t\t\t\t\t</svg>\r\n\t\t\t\t</a>\r\n\r\n\t\t\t\t<ul class=\"dropdown-menu small\">\r\n\t\t\t\t\t<li>\r\n\t\t\t\t\t\t<a class=\"dropdown-item\" data-action=\"copy_link\">\r\n\t\t\t\t\t\t\t{{ __('Copy Link') }}\r\n\t\t\t\t\t\t</a>\r\n\t\t\t\t\t\t{% if (frappe.is_mobile()) { %}\r\n\t\t\t\t\t\t<a class=\"dropdown-item\" href=\"{{ doc._url }}\" title=\"{{ __(\"Open Communication\") }}\">\r\n\t\t\t\t\t\t\t{{  __(\"Open Communication\") }}\r\n\t\t\t\t\t\t</a>\r\n\t\t\t\t\t\t{% } %}\r\n\t\t\t\t\t</li>\r\n\t\t\t\t</ul>\r\n\t\t\t</div>\r\n\t\t</span>\r\n\t</span>\r\n\t<div class=\"content\">\r\n\t\t{{ doc.content }}\r\n\t</div>\r\n\t{% if (doc.attachments && doc.attachments.length) { %}\r\n\t<div style=\"margin-top: 10px\">\r\n\t{% $.each(doc.attachments, function(i, a) { %}\r\n\t<div class=\"ellipsis flex\">\r\n\t\t<a href=\"{%= encodeURI(a.file_url).replace(/#/g, \\'%23\\') %}\"\r\n\t\t\tclass=\"text-muted small\" target=\"_blank\" rel=\"noopener noreferrer\">\r\n\t\t\t<svg viewBox=\"0 0 16 16\" class=\"icon icon-xs\" xmlns=\"http://www.w3.org/2000/svg\">\r\n\t\t\t\t<path d=\"M14 7.66625L8.68679 12.8875C7.17736 14.3708 4.64151 14.3708 3.13208 12.8875C1.62264 11.4042 1.62264 8.91224 3.13208 7.42892L7.84151 2.80099C8.9283 1.733 10.6189 1.733 11.7057 2.80099C12.7925 3.86897 12.7925 5.53028 11.7057 6.59827L7.35849 10.8109C6.75472 11.4042 5.78868 11.4042 5.24528 10.8109C4.64151 10.2176 4.64151 9.26823 5.24528 8.73424L8.86792 5.17429\" stroke=\"currentColor\" stroke-miterlimit=\"10\" stroke-linecap=\"round\"/>\r\n\t\t\t</svg>\r\n\t\t\t{%= a.file_url.split(\"/\").slice(-1)[0] %}\r\n\t\t\t{% if (a.is_private) { %}\r\n\t\t\t\t<svg class=\"icon icon-xs\" style=\"color: var(--yellow-300)\"\r\n\t\t\t\t\txmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 16 16\">\r\n\t\t\t\t\t<path fill-rule=\"evenodd\" clip-rule=\"evenodd\" d=\"M8.077 1.45h-.055a3.356 3.356 0 00-3.387 3.322v.35H3.75a2 2 0 00-2 2v5.391a2 2 0 002 2h8.539a2 2 0 002-2V7.122a2 2 0 00-2-2h-.885v-.285A3.356 3.356 0 008.082 1.45h-.005zm2.327 3.672V4.83a2.356 2.356 0 00-2.33-2.38h-.06a2.356 2.356 0 00-2.38 2.33v.342h4.77zm-6.654 1a1 1 0 00-1 1v5.391a1 1 0 001 1h8.539a1 1 0 001-1V7.122a1 1 0 00-1-1H3.75zm4.27 4.269a.573.573 0 100-1.147.573.573 0 000 1.147zm1.573-.574a1.573 1.573 0 11-3.147 0 1.573 1.573 0 013.147 0z\" fill=\"currentColor\" stroke=\"currentColor\"></path>\r\n\t\t\t\t</svg>\r\n\t\t\t{% } %}\r\n\t\t</a>\r\n\t</div>\r\n\t{% }); %}\r\n\t</div>\r\n\t{% } %}\r\n</div>\r\n",
  "users_in_sidebar": "{% for (var i=0, l=users.length; i < l; i++) {\r\n\tvar u = users[i];\r\n%}\r\n\t<span class=\"avatar avatar-small {{ u.avatar_class || \"\" }}\" title=\"{{ u.title }}\">\r\n\t{% if (u.icon) { %}\r\n\t\t<i class=\"{{ u.icon }}\"></i>\r\n\t{% } else if(u.image) { %}\r\n\t\t<img class=\"media-object\" src=\"{{ u.image }}\" alt=\"{{ u.fullname }}\">\r\n\t{% } else { %}\r\n\t\t<div class=\"standard-image\" style=\"background-color: {{ u.color }};\">{{ u.abbr.substr(0,1) }}</div>\r\n\t{% } %}\r\n\t</span>\r\n{% } %}\r\n",
  "list_sidebar_stat": "{% if (stats.length) { %}\r\n<div class=\"dropdown-search mb-1\">\r\n\t<input type=\"text\"\r\n\t\tplaceholder=\"${__(\"Search\")}\"\r\n\t\tdata-element=\"search\"\r\n\t\tclass=\"dropdown-search-input form-control input-xs\"\r\n\t>\r\n</div>\r\n{% } %}\r\n{% if (!stats.length) { %}\r\n<li class=\"stat-no-records text-muted\">{{ __(\"No records tagged.\") }}</li>\r\n{% } else {\r\n\tfor (var i=0, l=stats.length; i < l; i++) {\r\n\t\tvar stat_label = stats[i][0];\r\n\t\tvar stat_count = stats[i][1];\r\n%}\r\n<li>\r\n\t<a class=\"stat-link dropdown-item flex justify-between group-by-item\" data-label=\"{{ stat_label }}\" data-value=\"{{ stat_label }}\" data-field=\"_user_tags\" href=\"#\" onclick=\"return false;\">\r\n\r\n\t\t<span class=\"stat-label\">\r\n\t\t\t{% if (applied_filter == stat_label) { %}\r\n\t\t\t\t<span class=\"applied\"> {{ frappe.utils.icon(\"check\", \"xs\") }} </span>\r\n\t\t\t{% } %}\r\n\t\t\t{{ __(stat_label) }}\r\n\t\t</span>\r\n\t\t<span>{{ stat_count }}</span>\r\n\t</a>\r\n</li>\r\n\t{% }\r\n} %}\r\n",
  "list_view_permission_restrictions": "<table class=\"table table-bordered\" style=\"margin: 0;\">\r\n\t<thead>\r\n\t\t<th>{{ __(\"Field\") }}</th>\r\n\t\t<th>{{ __(\"Value\") }}</th>\r\n\t</thead>\r\n\t<tbody>\r\n\t\t{% for (let condition of condition_list ) { %}\r\n\t\t\t{% for (let key in condition) { %}\r\n\t\t\t<tr>\r\n\t\t\t\t<td>{{ __(key) }}</td>\r\n\t\t\t\t<td>{{ frappe.utils.comma_or(condition[key]) }}</td>\r\n\t\t\t</tr>\r\n\t\t\t{% } %}\r\n\t\t{% } %}\r\n\t</tbody>\r\n</table>\r\n",
  "desktop_icon": "<div class=\"desktop-icon\">\r\n    <!-- The logo and the title are two anchors to the same place, because the subtitle below is a\r\n         link of its own and an anchor cannot nest inside another. The logo is hidden from the\r\n         accessibility tree so the tile offers one link to the app, not two. -->\r\n    <a class=\"icon-link\" href=\"#\" tabindex=\"-1\" aria-hidden=\"true\">\r\n        {% if (icon.logo_url) { %}\r\n            <div class=\"icon-container\">\r\n                <img class=\"app-icon\" src=\"{{ frappe.utils.escape_html(icon.logo_url) }}\" alt=\"{{ frappe.utils.escape_html(icon.label) }}\" />\r\n            </div>\r\n        {% } else { %}\r\n            {%= frappe.utils.desktop_icon(icon.label, \"gray\", \"md\", \"Solid\") %}\r\n        {% } %}\r\n    </a>\r\n    <div class=\"icon-caption\">\r\n        <a class=\"icon-title\" href=\"#\">{{ frappe.utils.escape_html(__(icon.label)) }}</a>\r\n        {% if (icon.desk_route) { %}\r\n        <a class=\"icon-subtitle\" href=\"{{ frappe.utils.escape_html(icon.desk_route) }}\">{{ frappe.utils.escape_html(__(\"Open in Desk\")) }}</a>\r\n        {% } %}\r\n    </div>\r\n</div>\r\n",
  "desktop_icons_item": "<a class=\"desktop-icon\" data-id=\"{{ icon.label}}\"  data-logo=\"{{ icon.logo_url }}\" data-icon=\"{{ icon.icon }}\" data-type=\"{{ icon.type }}\" style=\"text-decoration:none\">\r\n    {% if(frappe.utils.get_desktop_icon(icon.label, frappe.boot.desktop_icon_style ) && icon.icon_type != \"Folder\") %}\r\n        <div class=\"icon-container\">\r\n            <img class=\"app-icon\" src=\"{{ frappe.utils.get_desktop_icon(icon.label, frappe.boot.desktop_icon_style) }}\" alt=\"{{ icon.label }}\" />\r\n        </div>\r\n    {% else if (icon.logo_url || icon.icon_image) { %}\r\n        <div class=\"icon-container\">\r\n            <img class=\"app-icon\" src=\"{{ icon.logo_url || icon.icon_image }}\" alt=\"{{ icon.label }}\" />\r\n        </div>\r\n    {% } else if (icon.icon_type == \"Folder\") { %}\r\n        <div class=\"icon-container folder-icon\">\r\n\r\n        </div>\r\n    {% } else { %}\r\n            {%= frappe.utils.desktop_icon(icon.label, icon.bg_color || \"gray\") %}\r\n    {% } %}\r\n    {% if (!in_folder) { %}\r\n    <div class=\"icon-caption\">\r\n        <div class=\"icon-title\" data-toggle=\"tooltip\" data-original-title=\"{{ __(icon.label) }}\">{{ __(icon.label) }}</div>\r\n        <!-- <div class=\"icon-subtitle\"></div> -->\r\n    </div>\r\n    {% } %}\r\n    {% if(!icon.in_folder && !icon.restrict_removal) { %}\r\n    <div class=\"hide-button\" data-mode=\"hide\">\r\n        {%= frappe.utils.icon(\"x\") %}\r\n    </div>\r\n    {% } %}\r\n</a>\r\n",
  "edit_filter": "<div class=\"filter-box\">\r\n\t<div class=\"visible-xs flex justify-flex-end\">\r\n\t\t<span class=\"remove-filter\">\r\n\t\t\t{{ __(\"Remove\") }}\r\n\t\t</span>\r\n\t</div>\r\n\t<div class=\"list_filter row\">\r\n\t\t<div class=\"fieldname-select-area col-sm-4 ui-front form-group\"></div>\r\n\t\t<div class=\"col-sm-3 form-group\">\r\n\t\t\t<select class=\"condition form-control input-xs\">\r\n\t\t\t\t{% for condition in conditions %}\r\n\t\t\t\t<option value=\"{{condition[0]}}\">{{ condition[1] }}</option>\r\n\t\t\t\t{% endfor %}\r\n\t\t\t</select>\r\n\t\t</div>\r\n\t\t<div class=\"col-sm-4 form-group\">\r\n\t\t\t<div class=\"filter-field\"></div>\r\n\t\t\t<div class=\"text-muted small filter-description\"></div>\r\n\t\t</div>\r\n\t\t<div class=\"remove-filter col-sm-1 text-center hidden-xs\" tabindex=\"0\" role=\"button\">\r\n\t\t\t<svg class=\"icon icon-sm\">\r\n\t\t\t\t<use href=\"#icon-x\"></use>\r\n\t\t\t</svg>\r\n\t\t</div>\r\n\t</div>\r\n</div>\r\n",
  "group_by": "<div class=\"group-by-box\">\r\n\t<div class=\"visible-xs flex justify-flex-end\">\r\n\t\t<span class=\"remove-group-by\">\r\n\t\t\t{{ __(\"Remove\") }}\r\n\t\t</span>\r\n\t</div>\r\n\t<div class=\"list_groupby row\">\r\n\t\t<div class=\"col-sm-8 form-group\">\r\n\t\t\t<select class=\"group-by form-control input-xs\">\r\n\t\t\t\t<option value=\"\" disabled selected>{{ __(\"Select Group By...\") }}</option>\r\n\t\t\t\t{% for (var parent_doctype in group_by_conditions) { %}\r\n\t\t\t\t\t{% for (var val of group_by_conditions[parent_doctype]) { %}\r\n\t\t\t\t\t\t{% field_name = val.label || val.fieldname %}\r\n\t\t\t\t\t\t{% if(val.parent && doctype != val.parent) field_name += \" (\"+parent_doctype+\")\"  %}\r\n\t\t\t\t\t\t<option\r\n\t\t\t\t\t\t\tdata-doctype=\"{{parent_doctype}}\"\r\n\t\t\t\t\t\t\tvalue=\"{{val.fieldname}}\"\r\n\t\t\t\t\t\t\tdata-parent-doctype=\"{{doctype}}\"\r\n\t\t\t\t\t\t>\r\n\t\t\t\t\t\t\t{{ __(field_name, null, val.parent ) }}\r\n\t\t\t\t\t\t</option>\r\n\t\t\t\t\t{% } %}\r\n\t\t\t\t{% } %}\r\n\t\t\t</select>\r\n\t\t</div>\r\n\t\t<div class=\"col-sm-3 form-group\">\r\n\t\t\t<select class=\"aggregate-function form-control input-xs\">\r\n\t\t\t\t{% for condition in aggregate_function_conditions %}\r\n\t\t\t\t<option value=\"{{condition.name}}\">{{ __(condition.label) }}</option>\r\n\t\t\t\t{% endfor %}\r\n\t\t\t</select>\r\n\t\t</div>\r\n\t\t<div class=\"col-sm-4 col-xs-12\" style=\"display: none\">\r\n\t\t\t<select class=\"aggregate-on form-control input-xs\">\r\n\t\t\t\t<option value=\"\" disabled selected>{{ __(\"Select Field...\") }}</option>\r\n\t\t\t</select>\r\n\t\t</div>\r\n\t\t<div class=\"groupby-actions pull-left col-sm-1 hidden-xs\">\r\n\t\t\t<span class=\"remove-group-by\">\r\n\t\t\t\t<svg class=\"icon icon-sm\">\r\n\t\t\t\t\t<use href=\"#icon-x\"></use>\r\n\t\t\t\t</svg>\r\n\t\t\t</span>\r\n\t\t</div>\r\n\t</div>\r\n</div>\r\n",
  "listing": "<div class=\"frappe-list\">\r\n\t<div class=\"list-filters\" style=\"display: none;\">\r\n\t</div>\r\n\r\n\t<div style=\"margin-bottom:9px\" class=\"list-toolbar-wrapper hide\">\r\n\t\t<div class=\"list-toolbar btn-group\" style=\"display:inline-block; margin-right: 10px;\">\r\n\t\t</div>\r\n\t</div>\r\n    <div style=\"clear:both\"></div>\r\n\t<div class=\"no-result text-center\" style=\"display: none;\">\r\n\t\t{%= no_result_message %}\r\n\t</div>\r\n\t<div class=\"result\">\r\n\t\t<div class=\"list-headers\"></div>\r\n        <div class=\"list-loading text-center\">\r\n        \t{%= frappe.messages.get_waiting_message(__(\"Loading\") + \"...\" ) %}\r\n        </div>\r\n\t\t<div class=\"result-list\"></div>\r\n\t</div>\r\n\t<div class=\"list-paging-area\">\r\n\t\t<div class=\"row\">\r\n\t\t\t<div class=\"col-xs-6\">\r\n\t\t\t\t<div class=\"btn-group btn-group-paging\">\r\n\t\t\t\t\t<button type=\"button\" class=\"btn btn-default btn-sm btn-info\" data-value=\"20\">20</button>\r\n\t\t\t\t\t<button type=\"button\" class=\"btn btn-default btn-sm\" data-value=\"100\">100</button>\r\n\t\t\t\t\t<button type=\"button\" class=\"btn btn-default btn-sm\" data-value=\"500\">500</button>\r\n\t\t\t\t</div>\r\n\t\t\t</div>\r\n\t\t\t<div class=\"col-xs-6 text-right\">\r\n\t\t\t\t<button class=\"btn btn-default btn-more btn-sm\">{%= _more %}...</button>\r\n\t\t\t</div>\r\n\t\t</div>\r\n\t</div>\r\n</div>\r\n",
  "page": "<div class=\"page-head flex\">\r\n\t<div class=\"container\">\r\n\t\t<div class=\"row flex-nowrap align-center page-head-content justify-between\">\r\n\t\t\t<div class=\"page-title\">\r\n\t\t\t\t<button class=\"btn-reset sidebar-toggle-btn navbar-brand\">\r\n\t\t\t\t\t<svg class=\"icon icon-md sidebar-toggle-placeholder\">\r\n\t\t\t\t\t\t<use href=\"#icon-menu\"></use>\r\n\t\t\t\t\t</svg>\r\n\t\t\t\t\t<span class=\"sidebar-toggle-icon\">\r\n\t\t\t\t\t\t<svg class=\"icon icon-md\">\r\n\t\t\t\t\t\t\t<use href=\"#icon-panel-left-close\">\r\n\t\t\t\t\t\t\t</use>\r\n\t\t\t\t\t\t</svg>\r\n\t\t\t\t\t</span>\r\n\t\t\t\t</button>\r\n\t\t\t\t<div class=\"flex title-area ellipsis\">\r\n\t\t\t\t\t<nav class=\"es-breadcrumbs navbar-breadcrumbs {{frappe.is_mobile() ? \"mobile-no-divider\" : \"\"}}\" aria-label=\"{{ __(\"Breadcrumb\") }}\"><ol></ol></nav>\r\n\t\t\t\t\t<button class=\"btn btn-default more-button hide\">\r\n\t\t\t\t\t\t<svg class=\"icon icon-sm\">\r\n\t\t\t\t\t\t\t<use href=\"#icon-ellipsis\">\r\n\t\t\t\t\t\t\t</use>\r\n\t\t\t\t\t\t</svg>\r\n\t\t\t\t\t</button>\r\n\t\t\t\t\t<span class=\"es-badge page-indicator-pill hide\" data-testid=\"page-status\"></span>\r\n\t\t\t\t</div>\r\n\t\t\t</div>\r\n\t\t\t<div class=\"align-center flex standard-items-section\">\r\n\t\t\t\t<button id=\"small-search-button\" class=\"btn-reset search-bar navbar-modal-search-mobile hidden\" aria-label=\"{{ __(\"Search\") }}\">\r\n\t\t\t\t\t<span class=\"search-icon\">\r\n\t\t\t\t\t\t<svg class=\"icon icon-sm\"><use href=\"#icon-search\"></use></svg>\r\n\t\t\t\t\t</span>\r\n\t\t\t\t</button>\r\n\t\t\t\t<div class=\"flex col page-actions justify-content-end {% if frappe.is_mobile() %} pl-0 {% endif %}\">\r\n\t\t\t\t\t<!-- buttons -->\r\n\t\t\t\t\t<div class=\"filters flex\"></div>\r\n\t\t\t\t\t<div class=\"custom-actions hide hidden-xs hidden-md\"></div>\r\n\t\t\t\t\t<div class=\"custom-mobile-actions\"></div>\r\n\t\t\t\t\t<div class=\"standard-actions flex\">\r\n\t\t\t\t\t\t<span class=\"page-icon-group hide hidden-xs hidden-sm\"></span>\r\n\t\t\t\t\t\t<div class=\"menu-btn-group hide\">\r\n\t\t\t\t\t\t\t{%= frappe.ui.button.html({\r\n\t\t\t\t\t\t\t\ticon: \"ellipsis\",\r\n\t\t\t\t\t\t\t\ttitle: __(\"Menu\"),\r\n\t\t\t\t\t\t\t\tcss_class: \"icon-btn menu-more-button\",\r\n\t\t\t\t\t\t\t}) %}\r\n\t\t\t\t\t\t\t<!-- hidden item store, not UI: add_dropdown_item writes <li><a> here\r\n\t\t\t\t\t\t\t(the returned jQuery is public API); frappe.ui.Dropdown snapshots it\r\n\t\t\t\t\t\t\tinto menu rows on every open — see page.js build_dropdown_options -->\r\n\t\t\t\t\t\t\t<ul class=\"dropdown-menu dropdown-menu-right\" role=\"presentation\"></ul>\r\n\t\t\t\t\t\t</div>\r\n\t\t\t\t\t\t{%= frappe.ui.button.html({ css_class: \"secondary-action hide\" }) %}\r\n\t\t\t\t\t\t<div class=\"actions-btn-group hide\">\r\n\t\t\t\t\t\t\t{%= frappe.ui.button.html({\r\n\t\t\t\t\t\t\t\tlabel: __(\"Actions\"),\r\n\t\t\t\t\t\t\t\ticon_right: \"chevrons-up-down\",\r\n\t\t\t\t\t\t\t\tvariant: \"solid\",\r\n\t\t\t\t\t\t\t}) %}\r\n\t\t\t\t\t\t\t<ul class=\"dropdown-menu dropdown-menu-right\" role=\"presentation\">\r\n\t\t\t\t\t\t\t</ul>\r\n\t\t\t\t\t\t</div>\r\n\t\t\t\t\t\t{%= frappe.ui.button.html({ variant: \"solid\", css_class: \"primary-action hide\" }) %}\r\n\t\t\t\t\t</div>\r\n\t\t\t\t</div>\r\n\t\t\t</div>\r\n\t\t</div>\r\n\t</div>\r\n</div>\r\n<div class=\"container page-body\">\r\n\t<div class=\"page-toolbar hide\">\r\n\t\t<div class=\"container\">\r\n\t\t</div>\r\n\t</div>\r\n\t<div class=\"page-wrapper\">\r\n\t\t<div class=\"page-content\">\r\n\t\t\t<div class=\"workflow-button-area btn-group pull-right hide\"></div>\r\n\t\t\t<div class=\"clearfix\"></div>\r\n\t\t</div>\r\n\t</div>\r\n</div>\r\n",
  "card": "<div class=\"frappe-card d-inline-flex flex-column px-2 py-2\">\r\n    {% if(!card.close_button) { %}\r\n    <div>\r\n        <div class=\"frappe-card-title-container\">\r\n            {%= frappe.utils.icon(card.icon, \"sm\", \"\", \"\", \"frappe-card-icon\") %}\r\n            <div class=\"frappe-card-title\">{{ card.title }}</div>\r\n        </div>\r\n        <div class=\"frappe-card-description\">{{ card.message }}</div>\r\n    </div>\r\n    {% } else { %}\r\n        <div class=\"frappe-card-title-container frappe-card-close-button\">\r\n            {% if !card.hide_icon %}\r\n                {%= frappe.utils.icon(card.icon, \"sm\", \"\", \"\", \"frappe-card-icon\") %}\r\n            {% endif %}\r\n            <span class=\"flex flex-column w-100\">\r\n                <div class=\"frappe-card-title\">{{ card.title }}</div>\r\n                <div class=\"frappe-card-description\">{{ card.message }}</div>\r\n            </span>\r\n            <span class=\"frappe-card-header-slot flex\"></span>\r\n            <button type=\"button\" class=\"close-button btn btn-default icon-btn\">\r\n                {%= frappe.utils.icon(\"x\", \"sm\") %}\r\n            </button>\r\n         </div>\r\n    {% } %}\r\n    <div class=\"frappe-card-actions flex\">\r\n            {% if(card.primary_action_label) { %}\r\n    <button class=\"frappe-card-button btn {%= card.primary_button_width ? 'w-100' : '' %}\">\r\n        {% if (card.primary_action_icon) %}\r\n            {{ frappe.utils.icon(card.primary_action_icon, \"sm\", \"\", \"\", \"\", true) }}\r\n        {% } %}\r\n        {{ card.primary_action_label }}\r\n        {% if card.primary_action_suffix_icon %}\r\n            {{ frappe.utils.icon(card.primary_action_suffix_icon, \"sm\", \"\", \"\", \"\", true) }}\r\n        {% endif %}\r\n    </button>\r\n    {% } %}\r\n    </div>\r\n</div>",
  "sidebar": "<div class=\"body-sidebar-container {%= expanded ? 'expanded' : ''%}\">\r\n\t\t<div class=\"body-sidebar\">\r\n\t\t\t<!-- The standard-items band: search, notifications and background tasks, as\r\n\t\t\t     full-width rows directly under the header and above the module's own items.\r\n\t\t\t     The dock carries none of them -- see Sidebar.add_standard_items. It sits outside\r\n\t\t\t     .body-sidebar-top, the box that scrolls, so it stays put when a long sidebar\r\n\t\t\t     scrolls under it. -->\r\n\t\t\t<div class=\"standard-items-band\"></div>\r\n\t\t\t<div class=\"body-sidebar-top\">\r\n\t\t\t\t<div class=\"sidebar-items\">\r\n\t\t\t\t</div>\r\n\t\t\t</div>\r\n\t\t\t<div class=\"body-sidebar-cards\"></div>\r\n\t\t\t<div class=\"body-sidebar-bottom\">\r\n\t\t\t\t<div class=\"promotional-banners\"></div>\r\n\t\t\t\t<div class=\"nav-item dropdown-navbar-user dropdown-mobile mt-3\">\r\n\t\t\t\t\t<a\r\n\t\t\t\t\t\tclass=\"align-center btn-reset flex nav-link sidebar-user-button\"\r\n\t\t\t\t\t\tstyle=\"width: 100%; min-height: 40px;\"\r\n\t\t\t\t\t\taria-label=\"{{ __(\"User Menu\") }}\"\r\n\t\t\t\t\t>\r\n\t\t\t\t\t\t<div> {{ avatar }} </div>\r\n\t\t\t\t\t\t<!-- The two lines take their size and their grey from the tokens that the\r\n\t\t\t\t\t\t     header title and subtitle take theirs from (see sidebar.scss), so the\r\n\t\t\t\t\t\t     Bootstrap classes .text-small, .text-secondary and .w-75 are off them:\r\n\t\t\t\t\t\t     each is a size or a grey from another system, and .text-secondary\r\n\t\t\t\t\t\t     carries an !important. Note: no apostrophes in this file. The template\r\n\t\t\t\t\t\t     compiler escapes only one per segment (see microtemplate.js), and a\r\n\t\t\t\t\t\t     second one is a syntax error in the compiled function, swallowed by a\r\n\t\t\t\t\t\t     catch that then hands back undefined. -->\r\n\t\t\t\t\t\t<div class=\"avatar-name-email overflow-hidden\" style=\"margin-left: 8px;\">\r\n\t\t\t\t\t\t\t<span class=\"d-block text-truncate\">\r\n\t\t\t\t\t\t\t\t{{ frappe.session.user_fullname }}\r\n\t\t\t\t\t\t\t</span>\r\n\t\t\t\t\t\t\t<span class=\"d-block text-truncate\">\r\n\t\t\t\t\t\t\t\t{{ frappe.session.user_email }}\r\n\t\t\t\t\t\t\t</span>\r\n\t\t\t\t\t\t</div>\r\n\t\t\t\t\t</a>\r\n\t\t\t\t</div>\r\n\t\t\t</div>\r\n\t\t</div>\r\n\t\t<!-- The panel edge, which collapses the panel to its rail and back from anywhere along\r\n\t\t     it, and the arrow that shows while the pointer is on it. Both sit half over the page,\r\n\t\t     so they are mounted beside the panel rather than in it: the panel clips anything that\r\n\t\t     overhangs it. The arrow is the one a keyboard reaches, so the edge is hidden from\r\n\t\t     assistive tech rather than being a second control with the same name. -->\r\n\t\t<div class=\"sidebar-edge\" aria-hidden=\"true\"></div>\r\n\t\t<button class=\"btn-reset sidebar-collapse-arrow\" type=\"button\">\r\n\t\t\t{%= frappe.utils.icon(\"chevron-left\", \"xs\", \"\", \"\", \"current-color\", true) %}\r\n\t\t</button>\r\n\t\t<div class=\"overlay\" style=\"z-index: 1021;\"></div>\r\n\t\t<div class=\"user-onboarding\"></div>\r\n\t</div>\r\n</div>\r\n",
  "sidebar_header": "<a class=\"sidebar-header shell-header\" style=\"text-decoration: none;\">\r\n<div class=\"header-logo\">{%= header_icon %}</div>\r\n<div class=\"title-container\">\r\n    <div class=\"sidebar-item-label header-title\" data-name-style=\"{%=frappe.boot.app_name_style%}\">\r\n            {%= __(workspace_title) %}\r\n    </div>\r\n</div>\r\n<button class=\"btn-reset drop-icon\" aria-label=\"{%= __('Sidebar Menu') %}\">\r\n    {%= frappe.utils.icon(\"chevron-down\", \"sm\", \"\", \"\", \"\", true) %}\r\n</button>\r\n</a>\r\n",
  "sidebar_item": "<div\r\n    class=\"sidebar-item-container {%= item.is_editable ? 'is-draggable' : '' %} {% if (item.type == 'Section Break') { %}section-item{% } %}\"\r\n    item-name=\"{{ item.label }}\"\r\n    data-id=\"{{ item.label }}\"\r\n>\r\n    <div\r\n        class=\"standard-sidebar-item {%= item.indent ? 'indent' : '' %}\">\r\n\r\n        {% if (item.type == \"Section Break\" && item.indent != 1) { %}\r\n            <div class=\"divider hidden\"></div>\r\n            <div class=\"item-anchor section-break\">\r\n                <span class=\"sidebar-item-label\">{{ item.label }}</span>\r\n                <div class=\"sidebar-item-control\"></div>\r\n            </div>\r\n        {% } else if (item.type == \"Spacer\") { %}\r\n\t\t\t<div class=\"item-anchor\" style=\"pointer-events: none;\">\r\n\r\n\t\t\t</div>\r\n\t\t{% } else  { %}\r\n            <a\r\n                {% if (path) { %}\r\n                    href=\"{{ path }}\"\r\n                    target=\"{%= item.link_type === \"URL\" && item.open_in_new_tab ? \"_blank\" : \"\" %}\"\r\n                {% } %}\r\n                class=\"item-anchor\"\r\n                data-link-type=\"{{ item.link_type || \"\" }}\"\r\n            >\r\n                {% if (item.icon && !item.show_arrow && !hide_icon) { %}\r\n                    <span class=\"sidebar-item-icon\" item-icon=\"{{ item.icon }}\">\r\n                        {%= frappe.utils.icon(item.icon, \"sm\", \"\", \"\", \"current-color\", true) %}\r\n                    </span>\r\n                {% } %}\r\n                <span class=\"sidebar-item-label\">{{ item.label }}</span>\r\n                {% if (item.suffix) { %}\r\n                     <span class=\"sidebar-item-suffix\">{{ item.suffix }}</span>\r\n                {% } %}\r\n                {% if (!item.show_arrow) { %}\r\n                <div class=\"sidebar-item-control\"></div>\r\n                {% } %}\r\n            </a>\r\n        {% } %}\r\n    </div>\r\n    <div class=\"sidebar-child-item nested-container\"></div>\r\n</div>",
  "side_panel": "<div class=\"side-panel hidden\">\r\n\t<div class=\"side-panel-resizer\" title=\"{%= __(\"Drag to resize\") %}\"></div>\r\n\t<div class=\"side-panel-header flex align-center\">\r\n\t\t<div class=\"side-panel-heading flex align-center text-base\">\r\n\t\t\t<span class=\"side-panel-doctype\"></span>\r\n\t\t\t<span class=\"side-panel-sep\">/</span>\r\n\t\t\t<span class=\"side-panel-title ellipsis text-base-semibold\"></span>\r\n\t\t\t<span class=\"side-panel-indicator\"></span>\r\n\t\t</div>\r\n\t\t<div class=\"side-panel-actions flex align-center\"></div>\r\n\t</div>\r\n\t<div class=\"side-panel-body flex-1\"></div>\r\n</div>\r\n",
  "sort_selector": "<div class=\"sort-selector\">\r\n\t<div class=\"btn-group\">\r\n\t\t<button class=\"btn btn-default btn-sm btn-order\"\r\n\t\t\tdata-value=\"{{ sort_order }}\"\r\n\t\t\ttitle=\"{{ sort_order===\"desc\" ? __(\"descending\") : __(\"ascending\") }}\">\r\n\t\t\t<span class=\"sort-order\">\r\n\t\t\t\t<svg class=\"icon icon-sm\">\r\n\t\t\t\t\t<use href=\"#icon-{{ sort_order===\"desc\" ? \"arrow-down-wide-narrow\" : \"arrow-up-narrow-wide\" }}\"></use>\r\n\t\t\t\t</svg>\r\n\t\t\t</span>\r\n\t\t</button>\r\n\t\t<button type=\"button\" class=\"btn btn-default btn-sm sort-selector-button text-nowrap\" data-toggle=\"dropdown\">\r\n\t\t\t<span class=\"dropdown-text hidden-sm\">{{ __(sort_by_label, null, doctype) }}</span>\r\n\t\t\t<span>{{ frappe.utils.icon(\"chevron-down\") }}</span>\r\n\t\t\t<ul class=\"dropdown-menu dropdown-menu-right\">\r\n\t\t\t\t{% for value in options %}\r\n\t\t\t\t<li>\r\n\t\t\t\t\t<a class=\"dropdown-item option\" data-value=\"{{ value.fieldname }}\">\r\n\t\t\t\t\t\t{{ __(value.label, null, doctype) }}\r\n\t\t\t\t\t</a>\r\n\t\t\t\t</li>\r\n\t\t\t\t{% endfor %}\r\n\t\t\t</ul>\r\n\t\t</button>\r\n\t</div>\r\n</div>\r\n",
  "navbar": "<div class=\"sticky-top\">\r\n\t{% if (!navbar_settings.dismissible_announcement_widget || !localStorage.getItem(\"dismissed_announcement_widget\")) && strip_html(navbar_settings.announcement_widget) != '' %}\r\n\t<div class=\"announcement-widget form-message p-2 m-0\" style=\"position: relative; z-index: -1; border-radius: 0; background-color: {{ navbar_settings.announcement_widget_color || 'var(--bg-blue)' }};\">\r\n\t\t<div class=\"container flex justify-between align-center mx-auto\">\r\n\t\t\t{{ navbar_settings.announcement_widget }}\r\n\t\t\t{% if navbar_settings.dismissible_announcement_widget %}\r\n\t\t\t<div class=\"close-message p-0 mr-2\" style=\"position: relative;\">\r\n\t\t\t{{ frappe.utils.icon(\"x\") }}\r\n\t\t\t{% endif %}\r\n\t\t\t</div>\r\n\t\t</div>\r\n\t</div>\r\n\t{% endif %}\r\n\r\n</div>\r\n",
  "search": "<div class=\"search-results flex\">\r\n\t<div class=\"col-md-2 col-sm-3 hidden-xs layout-side-section search-shortcuts-sidebar\">\r\n\t\t<ul class=\"overlay-sidebar list-unstyled search-sidebar\"></ul>\r\n\t</div>\r\n\t<div class=\"col-md-10 col-sm-9 layout-main-section search-main-column\">\r\n\t\t<div class=\"global-search-doctype-filters hide\"></div>\r\n\t\t<div class=\"results-area\"></div>\r\n\t</div>\r\n</div>\r\n",
  "workspace_loading_skeleton": "<div class=\"workspace-skeleton mt-3\">\r\n\t<div class=\"widget-group\">\r\n\t\t<div class=\"widget-group-head skeleton-header\">\r\n\t\t\t<div class=\"widget-group-title skeleton-card\"></div>\r\n\t\t</div>\r\n\t\t<div class=\"widget-group-body grid-col-3\">\r\n\t\t\t<div class=\"widget shortcut-widget-box skeleton-card\"></div>\r\n\t\t\t<div class=\"widget shortcut-widget-box skeleton-card\"></div>\r\n\t\t\t<div class=\"widget shortcut-widget-box skeleton-card\"></div>\r\n\t\t</div>\r\n\t</div>\r\n\t<div class=\"widget-group skeleton-body\">\r\n\t\t<div class=\"widget-group-head skeleton-header\">\r\n\t\t\t<div class=\"widget-group-title skeleton-card\"></div>\r\n\t\t</div>\r\n\t\t<div class=\"widget-group-body grid-col-3\">\r\n\t\t\t<div class=\"widget links-widget-box skeleton-card\"></div>\r\n\t\t\t<div class=\"widget links-widget-box skeleton-card\"></div>\r\n\t\t\t<div class=\"widget links-widget-box skeleton-card\"></div>\r\n\t\t\t<div class=\"widget links-widget-box skeleton-card\"></div>\r\n\t\t\t<div class=\"widget links-widget-box skeleton-card\"></div>\r\n\t\t</div>\r\n\t</div>\r\n</div>\r\n",
  "workspace_sidebar_loading_skeleton": "<div class=\"workspace-sidebar-skeleton\">\r\n\t<div class=\"widget-group-body\">\r\n\t\t<div class=\"widget sidebar-box skeleton-card\"></div>\r\n\t\t<div class=\"widget sidebar-box child skeleton-card\"></div>\r\n\t\t<div class=\"widget sidebar-box child skeleton-card\"></div>\r\n\t\t<div class=\"widget sidebar-box skeleton-card\"></div>\r\n\t</div>\r\n\t<div class=\"widget-group-body\">\r\n\t\t<div class=\"widget sidebar-box skeleton-card\"></div>\r\n\t\t<div class=\"widget sidebar-box skeleton-card\"></div>\r\n\t\t<div class=\"widget sidebar-box skeleton-card\"></div>\r\n\t\t<div class=\"widget sidebar-box child skeleton-card\"></div>\r\n\t\t<div class=\"widget sidebar-box child skeleton-card\"></div>\r\n\t\t<div class=\"widget sidebar-box child skeleton-card\"></div>\r\n\t\t<div class=\"widget sidebar-box child skeleton-card\"></div>\r\n\t\t<div class=\"widget sidebar-box skeleton-card\"></div>\r\n\t\t<div class=\"widget sidebar-box skeleton-card\"></div>\r\n\t\t<div class=\"widget sidebar-box skeleton-card\"></div>\r\n\t\t<div class=\"widget sidebar-box skeleton-card\"></div>\r\n\t\t<div class=\"widget sidebar-box skeleton-card\"></div>\r\n\t</div>\r\n</div>",
  "image_view_item_row": "<div class=\"image-view-item has-checkbox ellipsis\">\r\n\t<div class=\"image-view-header doclist-row\">\r\n\t\t<div class=\"list-value\">\r\n\t\t{{ subject }}\r\n\t\t</div>\r\n\t</div>\r\n\t<!-- Image -->\r\n\t<div class=\"image-view-body\">\r\n\t\t<a  data-name=\"{{ data.name }}\"\r\n\t\t\ttitle=\"{{ data.name }}\"\r\n\t\t\thref=\"/desk/Form/{{ data.doctype }}/{{ data.name }}\"\r\n\t\t>\r\n\t\t\t<div class=\"image-field\"\r\n\t\t\t\tdata-name=\"{{ data.name }}\"\r\n\t\t\t\tstyle=\"\r\n\t\t\t\t{% if (!data._image_url) { %}\r\n\t\t\t\t\tbackground-color: {{ color }};\r\n\t\t\t\t{% } %}\r\n\t\t\t\tborder: 0px;\"\r\n\t\t\t>\r\n\t\t\t\t{% if (!data._image_url) { %}\r\n\t\t\t\t<span class=\"placeholder-text\">\r\n\t\t\t\t\t{%= frappe.get_abbr(data._title) %}\r\n\t\t\t\t</span>\r\n\t\t\t\t{% } %}\r\n\t\t\t\t{% if (data._image_url) { %}\r\n\t\t\t\t<img data-name=\"{{ data.name }}\" src=\"{{ data._image_url }}\" alt=\"{{data.title}}\">\r\n\t\t\t\t{% } %}\r\n\t\t\t\t<button class=\"btn btn-default zoom-view\" data-name=\"{{data.name}}\">\r\n\t\t\t\t\t{%= frappe.utils.icon(\"zoom-in\", \"sm\") %}\r\n\t\t\t\t</button>\r\n\t\t\t</div>\r\n\t\t</a>\r\n\t</div>\r\n</div>\r\n",
  "photoswipe_dom": "\r\n\r\n<!-- http://photoswipe.com/documentation/getting-started.html -->\r\n<!-- Root element of PhotoSwipe. -->\r\n<div class=\"pswp\" tabindex=\"-1\" role=\"dialog\" aria-hidden=\"true\">\r\n\r\n\t<!-- Background of PhotoSwipe.\r\n\t\t It's a separate element as animating opacity is faster than rgba(). -->\r\n\t<div class=\"pswp__bg\"></div>\r\n\r\n\t<!-- Slides wrapper with overflow:hidden. -->\r\n\t<div class=\"pswp__scroll-wrap\">\r\n\r\n\t\t<!-- Container that holds slides.\r\n\t\t\tPhotoSwipe keeps only 3 of them in the DOM to save memory.\r\n\t\t\tDo not modify these 3 pswp__item elements, data is added later on. -->\r\n\t\t<div class=\"pswp__container\">\r\n\t\t\t<div class=\"pswp__item\"></div>\r\n\t\t\t<div class=\"pswp__item\"></div>\r\n\t\t\t<div class=\"pswp__item\"></div>\r\n\t\t</div>\r\n\r\n\t\t<div class=\"pswp__more-items\">\r\n\r\n\t\t</div>\r\n\r\n\t\t<!-- Default (PhotoSwipeUI_Default) interface on top of sliding area. Can be changed. -->\r\n\t\t<div class=\"pswp__ui pswp__ui--hidden\">\r\n\r\n\t\t\t<div class=\"pswp__top-bar\">\r\n\r\n\t\t\t\t<!--  Controls are self-explanatory. Order can be changed. -->\r\n\r\n\t\t\t\t<div class=\"pswp__counter\"></div>\r\n\r\n\t\t\t\t<button class=\"pswp__button pswp__button--close\" title=\"Close (Esc)\"></button>\r\n\r\n\t\t\t\t<button class=\"pswp__button pswp__button--share\" title=\"Share\"></button>\r\n\r\n\t\t\t\t<button class=\"pswp__button pswp__button--fs\" title=\"Toggle fullscreen\"></button>\r\n\r\n\t\t\t\t<button class=\"pswp__button pswp__button--zoom\" title=\"Zoom in/out\"></button>\r\n\r\n\t\t\t\t<!-- Preloader demo http://codepen.io/dimsemenov/pen/yyBWoR -->\r\n\t\t\t\t<!-- element will get class pswp__preloader--active when preloader is running -->\r\n\t\t\t\t<div class=\"pswp__preloader\">\r\n\t\t\t\t\t<div class=\"pswp__preloader__icn\">\r\n\t\t\t\t\t  <div class=\"pswp__preloader__cut\">\r\n\t\t\t\t\t\t<div class=\"pswp__preloader__donut\"></div>\r\n\t\t\t\t\t  </div>\r\n\t\t\t\t\t</div>\r\n\t\t\t\t</div>\r\n\t\t\t</div>\r\n\r\n\t\t\t<div class=\"pswp__share-modal pswp__share-modal--hidden pswp__single-tap\">\r\n\t\t\t\t<div class=\"pswp__share-tooltip\"></div>\r\n\t\t\t</div>\r\n\r\n\t\t\t<button class=\"pswp__button pswp__button--arrow--left\" title=\"Previous (arrow left)\">\r\n\t\t\t</button>\r\n\r\n\t\t\t<button class=\"pswp__button pswp__button--arrow--right\" title=\"Next (arrow right)\">\r\n\t\t\t</button>\r\n\r\n\t\t\t<div class=\"pswp__caption\">\r\n\t\t\t\t<div class=\"pswp__caption__center\"></div>\r\n\t\t\t</div>\r\n\r\n\t\t</div>\r\n\r\n\t</div>\r\n\r\n</div>\r\n",
  "kanban_board": "<div class=\"kanban\">\r\n\t<div class=\"kanban-column add-new-column\">\r\n\t\t<div class=\"kanban-column-title compose-column\">\r\n\t\t\t<a> + {{ __(\"Add Column\") }}</a>\r\n\t\t</div>\r\n\t\t<form class=\"compose-column-form kanban-column-title\">\r\n\t\t\t<input class=\"new-column-title\" name=\"title\" type=\"text\" autocomplete=\"off\">\r\n\t\t</form>\r\n\t</div>\r\n\t<div class=\"kanban-empty-state text-muted text-center\" style=\"display: none;\">\r\n\t\t{{ __(\"Loading...\") }}\r\n\t</div>\r\n</div>",
  "kanban_card": "<div class=\"kanban-card-wrapper {{ disable_click }}\" data-name=\"{{encodeURIComponent(name)}}\">\r\n\t<div class=\"kanban-card content\">\r\n\t\t<div class=\"kanban-card-body\">\r\n\t\t\t<div class=\"kanban-title-area\">\r\n\t\t\t\t<div class=\"kanban-card-header\">\r\n\t\t\t\t\t{{ avatar_html }}\r\n\t\t\t\t\t<a href=\"{{ form_link }}\" class=\"kanban-card-title-link\">\r\n\t\t\t\t\t\t<div class=\"kanban-card-title ellipsis\" title=\"{{title}}\">\r\n\t\t\t\t\t\t\t{{ title }}\r\n\t\t\t\t\t\t</div>\r\n\t\t\t\t\t</a>\r\n\t\t\t\t</div>\r\n\t\t\t\t{% if(doc_content) { %}\r\n\t\t\t\t<div class=\"kanban-card-doc text-muted\">\r\n\t\t\t\t\t{{ doc_content }}\r\n\t\t\t\t</div>\r\n\t\t\t\t{% } %}\r\n\t\t\t</div>\r\n\t\t\t<div class=\"kanban-card-meta\">\r\n\t\t\t</div>\r\n\t\t</div>\r\n\t</div>\r\n</div>\r\n",
  "kanban_column": "<div class=\"kanban-column\" data-column-value=\"{{title}}\" style=\"background-color: var(--kanban-column-bg);\">\r\n\t<div class=\"kanban-column-header\">\r\n\t\t<span class=\"kanban-column-title\">\r\n\t\t\t<span class=\"kanban-col-dot indicator {{indicator}}\"></span>\r\n\t\t\t<span class=\"kanban-title ellipsis\" title=\"{{title}}\">{{ __(title) }}</span>\r\n\t\t\t<span class=\"kanban-column-count es-badge\" data-variant=\"subtle\" data-size=\"sm\">0</span>\r\n\t\t</span>\r\n\t\t<div class=\"column-options dropdown pull-right\">\r\n\t\t\t<a data-toggle=\"dropdown\" aria-haspopup=\"true\" aria-expanded=\"false\">\r\n\t\t\t\t<svg class=\"icon icon-sm\">\r\n\t\t\t\t\t<use href=\"#icon-ellipsis\"></use>\r\n\t\t\t\t</svg>\r\n\t\t\t</a>\r\n\t\t\t<ul class=\"dropdown-menu\" style=\"max-height: 300px; overflow-y: auto;\">\r\n\t\t\t\t<li><a class=\"dropdown-item\" data-action=\"archive\">{{ __(\"Archive\") }}</a></li>\r\n\t\t\t</ul>\r\n\t\t</div>\r\n\t</div>\r\n\t<div class=\"add-card\">\r\n\t\t<div class=\"ellipsis\">\r\n\t\t\t+ {{ __(\"Add {0}\", [__(doctype)]) }}\r\n\t\t</div>\r\n\t</div>\r\n\t<div class=\"kanban-card new-card-area\">\r\n\t\t<textarea name=\"title\"></textarea>\r\n\t</div>\r\n\t<div class=\"kanban-cards\">\r\n\t</div>\r\n</div>",
  "print_grid": "<!-- title -->\r\n{% if title %}\r\n<h2 class=\"text-center\">{{ __(title) }}</h2>\r\n<hr>\r\n{% endif %}\r\n\r\n{% if subtitle %}\r\n\t{{ subtitle }}\r\n\t<hr>\r\n{% endif %}\r\n\r\n<table class=\"table table-bordered\">\r\n\t<!-- heading -->\r\n\t<thead>\r\n\t\t<tr>\r\n\t\t\t<th> # </th>\r\n\r\n\t\t{% for col in columns %}\r\n\t\t\t{% if col.name && col._id !== \"_check\" %}\r\n\t\t\t<th\r\n\t\t\t\t{% if col.minWidth %}\r\n\t\t\t\t\tstyle=\"min-width: {{ col.minWidth }}px\"\r\n\t\t\t\t{% endif %}\r\n\t\t\t\t{% if frappe.model.is_numeric_field(col.fieldtype) %}\r\n\t\t\t\t\tclass=\"text-right\"\r\n\t\t\t\t{% endif %}\r\n\t\t\t>\r\n\t\t\t\t{{ __(col.name) }}</th>\r\n\t\t\t{% endif %}\r\n\t\t{% endfor %}\r\n\t\t</tr>\r\n\t</thead>\r\n\t<!-- body -->\r\n\t<tbody>\r\n\t\t{% for row in data %}\r\n\t\t\t<tr style=\"height: 30px\">\r\n\r\n\t\t\t<td {% if row.bold == 1 %} style=\"font-weight: bold\" {% endif %}>\r\n\t\t\t\t<span> {{ row._index + 1 }} </span>\r\n\t\t\t</td>\r\n\r\n\t\t\t{% for col in columns %}\r\n\t\t\t\t{% if col.name && col._id !== \"_check\" %}\r\n\t\t\t\t\t{% var value = col.fieldname ? row[col.fieldname] : row[col.id] %}\r\n\t\t\t\t\t{% var longest_word = cstr(value).split(' ').reduce((longest, word) => word.length > longest.length ? word : longest, ''); %}\r\n\t\t\t\t\t<td {% if row.bold == 1 %} style=\"font-weight: bold\" {% endif %} {% if longest_word.length > 45 %} class=\"overflow-wrap-anywhere\" {% endif %}>\r\n\t\t\t\t\t\t<span {% if col._index == 0 %} style=\"padding-left: {%= cint(row.indent) * 2 %}em\" {% endif %}>\r\n\t\t\t\t\t\t\t{% format_data = row.is_total_row && [\"Currency\", \"Float\"].includes(col.fieldtype) ? data[0] : row %}\r\n\t\t\t\t\t\t\t{% if (row.is_total_row && col._index == 0) { %}\r\n\t\t\t\t\t\t\t\t{{ __(\"Total\") }}\r\n\t\t\t\t\t\t\t{% } else if (col.fieldtype == \"Check\") { %}\r\n\t\t\t\t\t\t\t\t{{ value == 1 ? \"✓\" : \"✗\" }}\r\n\t\t\t\t\t\t\t{% } else { %}\r\n\t\t\t\t\t\t\t\t{{\r\n\t\t\t\t\t\t\t\t\tcol.formatter\r\n\t\t\t\t\t\t\t\t\t\t? col.formatter(row._index, col._index, value, col, format_data, true)\r\n\t\t\t\t\t\t\t\t\t\t: col.format\r\n\t\t\t\t\t\t\t\t\t\t\t? col.format(value, row, col, format_data)\r\n\t\t\t\t\t\t\t\t\t\t\t: col.docfield\r\n\t\t\t\t\t\t\t\t\t\t\t\t? frappe.format(value, col.docfield)\r\n\t\t\t\t\t\t\t\t\t\t\t\t: value\r\n\t\t\t\t\t\t\t\t}}\r\n\t\t\t\t\t\t\t{% } %}\r\n\t\t\t\t\t\t</span>\r\n\t\t\t\t\t</td>\r\n\t\t\t\t{% endif %}\r\n\t\t\t{% endfor %}\r\n\t\t\t</tr>\r\n\t\t{% endfor %}\r\n\t</tbody>\r\n</table>\r\n",
  "print_tree": "<!DOCTYPE html>\r\n<html lang=\"en\">\r\n\t<head>\r\n\t\t<meta charset=\"utf-8\">\r\n\t\t<meta http-equiv=\"X-UA-Compatible\" content=\"IE=edge\">\r\n\t\t<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\r\n\t\t<meta name=\"description\" content=\"\">\r\n\t\t<meta name=\"author\" content=\"\">\r\n\t\t<title>{{ title }}</title>\r\n\t\t<link href=\"{{ base_url }}/assets/frappe/css/bootstrap.css\" rel=\"stylesheet\">\r\n\t\t<link rel=\"stylesheet\" type=\"text/css\" href=\"{{ base_url }}{{ print_format_css_path }}\">\r\n\t\t<style>\r\n\t\t\t{{ print_css }}\r\n\t\t</style>\r\n\t\t<style>\r\n\t\t\t/* Self-contained print styles for the row-mode tree markup.\r\n\t\t\t   This page loads no desk CSS, so colors are literal (no espresso\r\n\t\t\t   vars here) and :has() is avoided (unsupported by the old WebKit\r\n\t\t\t   in wkhtmltopdf). NOTE: this file compiles through the frappe\r\n\t\t\t   microtemplate engine, which cannot handle single quotes in\r\n\t\t\t   static text — never use apostrophes here. */\r\n\t\t\t.tree {\r\n\t\t\t\tfont-size: 13px;\r\n\t\t\t\tcolor: #1c2126;\r\n\t\t\t}\r\n\t\t\t.tree ul {\r\n\t\t\t\tmargin: 0;\r\n\t\t\t\tpadding: 0;\r\n\t\t\t\tlist-style: none;\r\n\t\t\t}\r\n\t\t\t.tree a,\r\n\t\t\t.tree-link {\r\n\t\t\t\ttext-decoration: none;\r\n\t\t\t\tcolor: inherit;\r\n\t\t\t\tcursor: default;\r\n\t\t\t}\r\n\t\t\tli.tree-node {\r\n\t\t\t\tdisplay: flex;\r\n\t\t\t\tflex-wrap: wrap;\r\n\t\t\t\talign-items: center;\r\n\t\t\t\tmargin: 0;\r\n\t\t\t}\r\n\t\t\t.tree-link {\r\n\t\t\t\tdisplay: flex;\r\n\t\t\t\tflex: 1 1 0%;\r\n\t\t\t\tmin-width: 0;\r\n\t\t\t\talign-items: center;\r\n\t\t\t\tmin-height: 26px;\r\n\t\t\t\tpadding: 2px 8px;\r\n\t\t\t}\r\n\t\t\t/* icon slot: chevron for groups, empty for leaves (alignment) */\r\n\t\t\t.tree-link > span:first-child {\r\n\t\t\t\tflex: none;\r\n\t\t\t\twidth: 20px;\r\n\t\t\t\tdisplay: flex;\r\n\t\t\t\talign-items: center;\r\n\t\t\t\tjustify-content: center;\r\n\t\t\t}\r\n\t\t\t.tree-link > span:first-child:not(.node-parent) svg {\r\n\t\t\t\tdisplay: none;\r\n\t\t\t}\r\n\t\t\t.tree-link svg {\r\n\t\t\t\twidth: 14px;\r\n\t\t\t\theight: 14px;\r\n\t\t\t\tstroke: #74808b;\r\n\t\t\t\tfill: none;\r\n\t\t\t\tstroke-width: 1.5;\r\n\t\t\t\tstroke-linecap: round;\r\n\t\t\t\tstroke-linejoin: round;\r\n\t\t\t}\r\n\t\t\t.tree-label {\r\n\t\t\t\tmargin-left: 4px;\r\n\t\t\t\tmin-width: 0;\r\n\t\t\t}\r\n\t\t\t/* elbow guides — same geometry as the screen styles */\r\n\t\t\tul.tree-children {\r\n\t\t\t\tflex: 1 1 100%;\r\n\t\t\t\tpadding-left: 24px;\r\n\t\t\t}\r\n\t\t\tul.tree-children > li.tree-node {\r\n\t\t\t\tposition: relative;\r\n\t\t\t}\r\n\t\t\tul.tree-children > li.tree-node::before {\r\n\t\t\t\tcontent: \"\";\r\n\t\t\t\tposition: absolute;\r\n\t\t\t\tleft: -6px;\r\n\t\t\t\ttop: 0;\r\n\t\t\t\theight: 13px;\r\n\t\t\t\twidth: 12px;\r\n\t\t\t\tborder-left: 1px solid #d1d8dd;\r\n\t\t\t\tborder-bottom: 1px solid #d1d8dd;\r\n\t\t\t}\r\n\t\t\tul.tree-children > li.tree-node:not(:last-child)::after {\r\n\t\t\t\tcontent: \"\";\r\n\t\t\t\tposition: absolute;\r\n\t\t\t\tleft: -6px;\r\n\t\t\t\ttop: 13px;\r\n\t\t\t\tbottom: 0;\r\n\t\t\t\tborder-left: 1px solid #d1d8dd;\r\n\t\t\t}\r\n\t\t\tul.tree-children > li.tree-node > .tree-link {\r\n\t\t\t\tmargin-left: 6px;\r\n\t\t\t\tpadding-left: 2px;\r\n\t\t\t}\r\n\t\t\t/* value column (balances) at the right edge of the row */\r\n\t\t\tli.tree-node > .balance-area {\r\n\t\t\t\tfloat: none;\r\n\t\t\t\tflex: none;\r\n\t\t\t\tmargin-left: auto;\r\n\t\t\t\tpadding: 2px 8px;\r\n\t\t\t\tfont-variant-numeric: tabular-nums;\r\n\t\t\t\twhite-space: nowrap;\r\n\t\t\t\tcolor: #383e42;\r\n\t\t\t}\r\n\t\t\t/* interactive chrome has no place on paper */\r\n\t\t\t.tree-node-toolbar,\r\n\t\t\t.tree-actions,\r\n\t\t\t.es-button {\r\n\t\t\t\tdisplay: none;\r\n\t\t\t}\r\n\t\t</style>\r\n  \t</head>\r\n\t<body>\r\n\t\t<svg id=\"frappe-symbols\" aria-hidden=\"true\" style=\"position: absolute; width: 0; height: 0; overflow: hidden;\" class=\"d-block\" xmlns=\"http://www.w3.org/2000/svg\">\r\n\t\t\t<symbol viewBox=\"0 0 24 24\" xmlns=\"http://www.w3.org/2000/svg\" id=\"icon-chevron-down\">\r\n\t\t\t\t<path d=\"m6 9 6 6 6-6\"></path>\r\n\t\t\t</symbol>\r\n\r\n\t\t\t<symbol viewBox=\"0 0 24 24\" xmlns=\"http://www.w3.org/2000/svg\" id=\"icon-chevron-right\">\r\n\t\t\t\t<path d=\"m9 18 6-6-6-6\"></path>\r\n\t\t\t</symbol>\r\n\r\n\t\t\t<symbol viewBox=\"0 0 24 24\" xmlns=\"http://www.w3.org/2000/svg\" id=\"icon-chevron-left\">\r\n\t\t\t\t<path d=\"m15 18-6-6 6-6\"></path>\r\n\t\t\t</symbol>\r\n\r\n\r\n\t\t</svg>\r\n\t\t<div class=\"print-format-gutter\">\r\n\t\t\t{% if print_settings.repeat_header_footer %}\r\n\t\t\t\t<div id=\"footer-html\" class=\"visible-pdf\">\r\n\t\t\t\t\t{% if print_settings.letter_head && print_settings.letter_head.footer %}\r\n\t\t\t\t\t\t<div class=\"letter-head-footer\">\r\n\t\t\t\t\t\t\t{{ print_settings.letter_head.footer }}\r\n\t\t\t\t\t\t</div>\r\n\t\t\t\t\t{% endif %}\r\n\t\t\t\t\t<p class=\"text-center small page-number visible-pdf\">\r\n\t\t\t\t\t\t{{ __(\"Page {0} of {1}\", [`<span class=\"page\"></span>`, `<span class=\"topage\"></span>`]) }}\r\n\t\t\t\t\t</p>\r\n\t\t\t\t</div>\r\n\t\t\t{% endif %}\r\n\r\n\t\t\t<div class=\"print-format {% if landscape %} landscape {% endif %}\">\r\n\t\t\t\t{% if print_settings.letter_head %}\r\n\t\t\t\t<div {% if print_settings.repeat_header_footer %} id=\"header-html\" class=\"hidden-pdf\" {% endif %}>\r\n\t\t\t\t\t<div class=\"letter-head\">{{ print_settings.letter_head.header }}</div>\r\n\t\t\t\t</div>\r\n\t\t\t\t\t{% endif %}\r\n\t\t\t\t\t<div class=\"tree tree-rows opened\">\r\n\t\t\t\t\t\t{{ tree }}\r\n\t\t\t\t\t</div>\r\n\t\t\t</div>\r\n\t\t</div>\r\n\t</body>\r\n</html>\r\n"
}

